impl SessionStoreConfig {
    /// List handoff records that have not yet been claimed by a target
    /// session (target-less / "open"), optionally scoped by the source
    /// session's `track_id` or by an explicit source `workspace_session_id`
    /// (R2/AC2: the unclaimed-handoff backlog query).
    pub fn list_open_handoffs(
        &self,
        track_id: Option<&str>,
        source_session_id: Option<&str>,
    ) -> Result<Vec<SessionHandoffRecord>, SessionError> {
        let mut records: Vec<SessionHandoffRecord> = self
            .all_handoff_records()?
            .into_iter()
            .filter(|record| record.target_session_id.is_none())
            .collect();

        if let Some(source) = source_session_id {
            records.retain(|record| record.workspace_session_id == source);
        }

        if let Some(track) = track_id {
            records.retain(|record| {
                self.read_session(&record.workspace_session_id)
                    .map(|session| session.track_id.as_deref() == Some(track))
                    .unwrap_or(false)
            });
        }

        records.sort_by(|left, right| left.created_at.cmp(&right.created_at));
        Ok(records)
    }

    /// Bind `target_session_id` onto an open handoff record and append the
    /// handoff id to the picking-up session's `picked_up_handoff_ids` (R2:
    /// the single-handoff bind-on-pickup write path). The full
    /// `pickup`/`fan_out`/`merge` verb surface is delivered by a follow-on
    /// ticket that builds on this write path.
    pub fn pickup_handoff(
        &self,
        handoff_id: &str,
        target_session_id: &str,
    ) -> Result<SessionHandoffRecord, SessionError> {
        let (source_session_id, mut record) =
            self.find_handoff_record(handoff_id)?;
        if record.target_session_id.is_some() {
            return Err(SessionError::HandoffAlreadyClaimed {
                handoff_id: handoff_id.to_string(),
            });
        }

        record.target_session_id = Some(target_session_id.to_string());

        let paths = self.runtime_paths_for_workspace(&source_session_id)?;
        let handoff_folder = paths.handoffs_dir.join(handoff_id);
        write_json(&handoff_folder.join("handoff.json"), &record)?;
        let markdown_content = render_handoff_record_markdown(&record);
        let handoff_md_path = handoff_folder.join("handoff.md");
        fs::write(&handoff_md_path, markdown_content).map_err(|source| {
            SessionError::Io {
                path: handoff_md_path.clone(),
                source,
            }
        })?;

        let target_paths = self.paths_for_session_id(target_session_id)?;
        let mut manifest: PersistedSessionManifest =
            read_json(&target_paths.manifest_path)?;
        if !manifest
            .picked_up_handoff_ids
            .iter()
            .any(|id| id == handoff_id)
        {
            manifest.picked_up_handoff_ids.push(handoff_id.to_string());
        }
        write_json(&target_paths.manifest_path, &manifest)?;

        Ok(record)
    }

    /// Locate a handoff record by scanning every session's `handoffs/` dir,
    /// returning its source session id alongside the record. Handoffs are
    /// stored per source session so the id alone does not resolve a path.
    fn find_handoff_record(
        &self,
        handoff_id: &str,
    ) -> Result<(String, SessionHandoffRecord), SessionError> {
        let sessions_root = self.sessions_root()?;
        if sessions_root.exists() {
            for entry in
                fs::read_dir(&sessions_root).map_err(|source| SessionError::Io {
                    path: sessions_root.clone(),
                    source,
                })?
            {
                let entry = entry.map_err(|source| SessionError::Io {
                    path: sessions_root.clone(),
                    source,
                })?;
                if !entry.file_type().map(|ft| ft.is_dir()).unwrap_or(false) {
                    continue;
                }
                let session_id = entry.file_name().to_string_lossy().into_owned();
                let handoff_json = entry
                    .path()
                    .join("handoffs")
                    .join(handoff_id)
                    .join("handoff.json");
                if handoff_json.exists() {
                    let record: SessionHandoffRecord = read_json(&handoff_json)?;
                    return Ok((session_id, record));
                }
            }
        }

        Err(SessionError::HandoffNotFound {
            handoff_id: handoff_id.to_string(),
        })
    }

    fn all_handoff_records(
        &self
    ) -> Result<Vec<SessionHandoffRecord>, SessionError> {
        let sessions_root = self.sessions_root()?;
        if !sessions_root.exists() {
            return Ok(vec![]);
        }

        let mut records = vec![];
        for entry in
            fs::read_dir(&sessions_root).map_err(|source| SessionError::Io {
                path: sessions_root.clone(),
                source,
            })?
        {
            let entry = entry.map_err(|source| SessionError::Io {
                path: sessions_root.clone(),
                source,
            })?;
            if !entry.file_type().map(|ft| ft.is_dir()).unwrap_or(false) {
                continue;
            }

            let handoffs_dir = entry.path().join("handoffs");
            if !handoffs_dir.exists() {
                continue;
            }

            for handoff_entry in fs::read_dir(&handoffs_dir).map_err(
                |source| SessionError::Io {
                    path: handoffs_dir.clone(),
                    source,
                },
            )? {
                let handoff_entry =
                    handoff_entry.map_err(|source| SessionError::Io {
                        path: handoffs_dir.clone(),
                        source,
                    })?;
                if !handoff_entry
                    .file_type()
                    .map(|ft| ft.is_dir())
                    .unwrap_or(false)
                {
                    continue;
                }

                let handoff_json = handoff_entry.path().join("handoff.json");
                if !handoff_json.exists() {
                    continue;
                }
                records.push(read_json(&handoff_json)?);
            }
        }

        Ok(records)
    }
}
